package adt;import java.io.Serializable;/** * * @author Lye Wei Keong * @param <T> */public class ArrayStack<T> implements StackInterface<T>, Serializable {  private T[] array;  private int topIndex;   private static final int DEFAULT_CAPACITY = 50;  public ArrayStack() {    this(DEFAULT_CAPACITY);  }  public ArrayStack(int initialCapacity) {    array = (T[]) new Object[initialCapacity];    topIndex = -1;  }  @Override  public void push(T newEntry) {    topIndex++;    if (topIndex < array.length) {      array[topIndex] = newEntry;    }  }  @Override  public T peek() {    T top = null;    if (!isEmpty()) {      top = array[topIndex];    }    return top;  }   @Override  public T pop() {    T top = null;    if (!isEmpty()) {      top = array[topIndex];      array[topIndex] = null;      topIndex--;    }     return top;  }   @Override  public boolean isEmpty() {    return topIndex < 0;  }   @Override  public void clear() {    topIndex = -1;  }   } 